"""Summarize explicit manual audit fields, preserving planned denominators."""
from pathlib import Path
import hashlib,json,time
AUDIT=Path(__file__).resolve().parent
records=[json.loads(p.read_text()) for p in sorted(AUDIT.glob('*.audit.json'))]
extracted={p.name.removesuffix('.extraction.json'):json.loads(p.read_text()) for p in AUDIT.glob('*.extraction.json')}
first=[r for r in records if r['stage']==1]
second=[r for r in records if r['stage']==2]
report={'schema':'finance-phase1-semantic-aggregate.v1','planned_sessions':40,'planned_initials':20,'planned_retrievals':20,'audited_sessions':len(records),'published_extractions':len(extracted),'audited_initials':len(first),'audited_retrievals':len(second),'faithful_initial_captures':sum(r['capture'].get('keyed_record_created') is True and r['capture'].get('full_agreement_faithful') is True for r in first),'late_first_captures':sum(r['capture'].get('late_first_capture') is True for r in second),'applicable_prior_record_sessions':sum(r['retrieval'].get('prior_record_sufficient_for_stage2') is True for r in second),'full_preexisting_record_reads':sum(r['retrieval'].get('full_entry_record_read') is True for r in second),'pre_edit_memory_use':sum(r['retrieval'].get('pre_edit_use_supported') is True for r in second),'direct_catalog_route':sum(r['retrieval'].get('route')=='direct from catalog' for r in second),'search_then_recall_route':sum(r['retrieval'].get('route')=='search then full recall' for r in second),'artifact_passes':sum(extracted[r['slot']]['artifact_passed'] for r in records),'artifact_correct_cases':sum(extracted[r['slot']]['artifact_correct'] for r in records),'artifact_total_cases':sum(extracted[r['slot']]['artifact_total'] for r in records),'independent_saved_stdout_verdicts_agree':all(extracted[r['slot']]['independent_artifact_check']['all_verdicts_agree'] and extracted[r['slot']]['independent_artifact_check']['all_expected_agree'] for r in records),'claims_require_review':[r['slot'] for r in records if r.get('unsupported_commentary')],'strict_six_stage_intersection':'not assessable in phase1; no clean full-lifecycle award','notes':['Counts summarize manually assessed components, not model-quality rankings.','Missing unpublished slots remain planned, not failures yet.','Read per-slot supplements for delivery corrections and qualified verification-scope findings.','Source/claim fidelity is separate from required fact fidelity.','Actual body use is observed; causal necessity is not inferred where code also retained policy.'],'audit_sha256':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(AUDIT.glob('*.json'))}}
path=AUDIT/f'progress-{time.time_ns()}.json'
with path.open('x') as f:json.dump(report,f,indent=2)
print(json.dumps({k:v for k,v in report.items() if k!='audit_sha256'},indent=2))
print(path)
